/* v358: assets usados somente na exportação de PDFs. Fontes permanecem incorporadas. */
(function(root){'use strict';const entries={"pdf-sans.ttf":"data:font/ttf;base64,","pdf-sans-bold.ttf":"data:font/ttf;base64,","pdf-sans-italic.ttf":"data:font/ttf;base64,","pdf-serif-bold.ttf":"data:font/ttf;base64,","pdf-serif-italic.ttf":"data:font/ttf;base64,","jornal-capa.jpg":"data:image/jpeg;base64,","jornal-diario.jpg":"data:image/jpeg;base64,","jornal-empresas.jpg":"data:image/jpeg;base64,","jornal-mundo.jpg":"data:image/jpeg;base64,"};
const base=new URL('./',root.location.href),owned=new Map(Object.entries(entries).map(([key,value])=>[value,key]));
function key(input){const value=typeof input==='string'?input:input?.url;if(owned.has(value))return owned.get(value);try{const u=new URL(value,base);return u.origin===base.origin&&u.pathname.startsWith(base.pathname)?u.pathname.slice(base.pathname.length):null}catch{return null}}
function bytes(value){const raw=atob(value.split(',')[1]),data=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)data[i]=raw.charCodeAt(i);return data}
const original=root.fetch.bind(root);root.fetch=function(input,options){const name=key(input),value=entries[name],method=String(options?.method||input?.method||'GET').toUpperCase();if(value&&method==='GET'){const type=value.slice(5,value.indexOf(';'));return Promise.resolve(new Response(bytes(value),{headers:{'Content-Type':type}}))}return original.apply(this,arguments)};
root.TraderResources=Object.freeze({has:input=>!!entries[key(input)],url:name=>entries[name]||name});
})(window);

